#!/usr/bin/env python3
"""
Generate ktoy's CExamples.kt from the pytoy C example programs.

For every examples/c/**/*.toyc in the sibling pytoy checkout (EXCLUDING 04-io/,
which uses read/write I/O and can't run headless-deterministically), this embeds
a triple:
    name -> (cSource, expectedToys)
where expectedToys is pytoy's compile_source(src, name) output — the golden,
byte-for-byte reference ktoy's compileSource must reproduce.

The source name handed to compile_source matters: it appears in the
"# Generated by toycc from <name>" header, so it must match between pytoy and
ktoy. We use os.path.basename(path) WITH the .toyc extension, exactly like
pytoy's own scripts/build_examples.py (the canonical builder). CCompilerTest.kt
calls compileSource(cSource, name) with the same name.

pytoy is a sibling of this repo (../pytoy), overridable with PYTOY:
    python3 scripts/gen_c_examples.py
    PYTOY=/path/to/pytoy python3 scripts/gen_c_examples.py
"""

import os
import sys
import glob

KTOY = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PYTOY = os.environ.get("PYTOY", os.path.join(os.path.dirname(KTOY), "pytoy"))
C_DIR = os.path.join(PYTOY, "examples", "c")
OUT = os.path.join(KTOY, "composeApp", "src", "commonTest", "kotlin",
                   "org", "bytefred", "ktoy", "core", "CExamples.kt")


def kotlin_triple_string(s):
    """Embed s in a Kotlin raw (triple-quote) string. Raw strings can't contain
    a literal triple-quote or a $ (interpolation); guard against both so a future
    example that breaks the embedding fails loudly here, not in the Kotlin build."""
    if '"""' in s:
        raise ValueError("content contains a triple-quote; can't embed raw")
    if '$' in s:
        raise ValueError("content contains '$'; would break Kotlin interpolation")
    return f'"""{s}"""'


def main():
    if not os.path.isdir(C_DIR):
        raise SystemExit(
            f"pytoy C examples not found at {C_DIR}. "
            f"Clone pytoy next to ktoy, or set PYTOY=/path/to/pytoy.")

    sys.path.insert(0, PYTOY)
    from pytoy.compiler import compile_source  # noqa: E402

    entries = []
    for path in sorted(glob.glob(os.path.join(C_DIR, "**", "*.toyc"),
                                 recursive=True)):
        # 04-io uses read()/write() memory-mapped I/O: not headless-deterministic.
        if os.sep + "04-io" + os.sep in path:
            continue
        name = os.path.basename(path)          # e.g. "sum3.toyc" (matches build_examples.py)
        with open(path) as f:
            src = f.read()
        asm = compile_source(src, name)        # golden reference assembly
        entries.append((name, src, asm))

    lines = [
        "package org.bytefred.ktoy.core",
        "",
        "/**",
        " * C compiler verification fixtures, embedded as strings (commonTest has",
        " * no portable filesystem access).",
        " *",
        " * For each example: the C source and the GOLDEN .toys produced by pytoy's",
        " * compile_source(src, name). ktoy's compileSource(src, name) must",
        " * reproduce the golden output byte-for-byte. The `name` is the .toyc file",
        " * basename (with extension), matching pytoy's scripts/build_examples.py, so",
        " * the \"# Generated by toycc from <name>\" headers agree.",
        " *",
        " * GENERATED from pytoy examples/c/ by scripts/gen_c_examples.py — do not",
        " * edit by hand; regenerate when the C examples or the compiler change.",
        " * 04-io/ examples are excluded (read/write I/O, not headless-deterministic).",
        " */",
        "",
        "data class CExample(val name: String, val cSource: String, val expectedToys: String)",
        "",
        "val C_EXAMPLES: List<CExample> = listOf(",
    ]
    for name, src, asm in entries:
        lines.append(f'    CExample(')
        lines.append(f'        name = {kotlin_triple_string(name)},')
        lines.append(f'        cSource = {kotlin_triple_string(src)},')
        lines.append(f'        expectedToys = {kotlin_triple_string(asm)},')
        lines.append(f'    ),')
    lines.append(")")
    lines.append("")

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w") as fh:
        fh.write("\n".join(lines))
    print(f"wrote {OUT} ({len(entries)} examples)")


if __name__ == "__main__":
    main()
